#ifndef RPS_RPS_META_H
#define RPS_RPS_META_H

#include <stddef.h>

/* Value types of the inputs and signals. */
typedef enum { RPS_BOOL = 0, RPS_INT32 = 1, RPS_REAL = 2 } RPS_Type;

/* One member of an Inputs or Signals structure. A flag's labels name its values (for a trip signal: 0
 * TRIP, 1 NORMAL); they are NULL for other types.
 */
typedef struct {
    const char *name;
    RPS_Type type;
    size_t offset;
    const char *unit;
    const char *label0;
    const char *label1;
} RPS_Field;

/* A module: its fields and functions, for tools that handle BP and CP alike. */
typedef struct {
    const char *name;
    const RPS_Field *inputs;
    size_t n_inputs;
    const RPS_Field *signals;
    size_t n_signals;
    size_t state_size;
    size_t inputs_size;
    size_t signals_size;
    void (*init)(void *state);
    void (*nominal_inputs)(void *inputs);
    void (*step)(void *state, const void *inputs, void *signals);
} RPS_Module;

/* An instance of the system: where its inputs and signals are in RPS_System_Inputs and RPS_System_Signals. */
typedef struct {
    const char *name;
    const RPS_Module *module;
    size_t inputs_offset;
    size_t signals_offset;
} RPS_Instance;

extern const RPS_Module RPS_MODULE_BP;
extern const RPS_Module RPS_MODULE_CP;
extern const RPS_Instance RPS_SYSTEM_INSTANCES[];
extern const size_t RPS_SYSTEM_N_INSTANCES;

/* A connection of the system: RPS_System_step sets input `to` (INSTANCE.input) to `from` (INSTANCE.signal
 * or INSTANCE.input) in every scan. RPS_System_Inputs keeps what was set there, not the value delivered.
 */
typedef struct {
    const char *to;
    const char *from;
} RPS_Connection;

extern const RPS_Connection RPS_SYSTEM_CONNECTIONS[];
extern const size_t RPS_SYSTEM_N_CONNECTIONS;

#endif  /* RPS_RPS_META_H */
